-- interview-batch4-diagrams.sql — 面試題庫補圖 批次 4
-- q3   兩級 NMOS 反相器（BSS138）：A=5V -> B=0V -> C=5V，ID(R452)=1.2mA
-- q8   SPI 串聯端接：Master 輸出的三條線在 Master 側串 22-33R，MISO 串在 Slave 側
-- q9   同步 vs 非同步 Buck：下管 FET vs 蕭特基（答案是同步）
-- q10  上管 OFF 的續流路徑：迴路經 body diode 與 L，不經 HS
-- q11  RC Snubber：串聯 RC 跨接 D-S，附振鈴 vs 阻尼波形對照
--
-- 兩道驗證都過：瀏覽器重疊實測 = 0；語意/幾何斷言全過（續流迴路封閉且避開 HS、
--   二極體陰極朝 SW、箭頭方向 3 右 1 左、振鈴曲線穿越穩態值 6 次而阻尼曲線 0 次過衝）
-- 用法：Supabase Dashboard → SQL Editor → 全部貼上 → Run。冪等，可重跑。

-- q3：兩級 NMOS 反相器，標出 A/B/C 位準
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="300" viewBox="0 0 520 300" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="300" fill="#ffffff"/><text x="260" y="20" fill="#1d2943" font-size="13" text-anchor="middle" font-weight="bold">BSS138 two-stage inverter: A HIGH -> B LOW -> C HIGH</text><text x="14" y="174" fill="#15803d" font-size="11" font-weight="bold">A = 5V</text><line x1="60" y1="170" x2="66" y2="170" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="resistor"><line x1="66" y1="170" x2="78" y2="170" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polyline points="78,170 81,163 87,177 93,163 99,177 102,170" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><line x1="102" y1="170" x2="114" y2="170" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="90" y="150" fill="#1d2943" font-size="11" text-anchor="middle">R1</text><text x="90" y="196" fill="#64748b" font-size="11" text-anchor="middle">10k</text><line x1="114" y1="170" x2="120" y2="170" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="rail"><line x1="230" y1="52" x2="230" y2="64" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="222" y1="52" x2="238" y2="52" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="244" y="58" fill="#b91c1c" font-size="11" font-weight="bold">12V</text><g data-sym="resistor"><line x1="230" y1="76" x2="230" y2="88" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polyline points="230,88 223,91 237,97 223,103 237,109 230,112" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><line x1="230" y1="112" x2="230" y2="124" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="244" y="96" fill="#1d2943" font-size="11">R452</text><text x="244" y="112" fill="#64748b" font-size="11">10k</text><line x1="230" y1="64" x2="230" y2="76" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="230" y1="124" x2="230" y2="150" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="176" y1="150" x2="230" y2="150" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="junction"><circle cx="230" cy="150" r="2.6" fill="#1f4fd1"/></g><text x="240" y="140" fill="#b91c1c" font-size="11" font-weight="bold">B = 0V</text><g data-sym="nmos"><line x1="120" y1="170" x2="134" y2="170" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="134" y1="158" x2="134" y2="182" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="141" y1="157" x2="141" y2="183" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="141" y1="162" x2="154" y2="162" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="154" y1="162" x2="154" y2="150" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="154" y1="150" x2="176" y2="150" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="141" y1="178" x2="154" y2="178" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="154" y1="178" x2="154" y2="190" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="154" y1="190" x2="176" y2="190" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="141" y1="170" x2="154" y2="170" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polygon points="147,166 147,174 141,170" fill="#1f4fd1" stroke="#1f4fd1" stroke-width="1"/><line x1="154" y1="170" x2="154" y2="178" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="168" y1="190" x2="168" y2="176" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polygon points="162,176 174,176 168,164" fill="none" stroke="#1f4fd1" stroke-width="2"/><line x1="162" y1="164" x2="174" y2="164" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="168" y1="164" x2="168" y2="150" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="120" y="206" fill="#1d2943" font-size="11" text-anchor="end" font-weight="bold">Q27</text><line x1="176" y1="190" x2="176" y2="214" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="ground"><line x1="176" y1="214" x2="176" y2="228" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="164" y1="228" x2="188" y2="228" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="168" y1="233" x2="184" y2="233" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="172" y1="238" x2="180" y2="238" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><polyline points="230,150 300,150 300,170 340,170" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><g data-sym="rail"><line x1="450" y1="52" x2="450" y2="64" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="442" y1="52" x2="458" y2="52" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="464" y="58" fill="#b91c1c" font-size="11" font-weight="bold">5V</text><g data-sym="resistor"><line x1="450" y1="76" x2="450" y2="88" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polyline points="450,88 443,91 457,97 443,103 457,109 450,112" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><line x1="450" y1="112" x2="450" y2="124" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="464" y="96" fill="#1d2943" font-size="11">R453</text><text x="464" y="112" fill="#64748b" font-size="11">10k</text><line x1="450" y1="64" x2="450" y2="76" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="450" y1="124" x2="450" y2="150" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="396" y1="150" x2="450" y2="150" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="junction"><circle cx="450" cy="150" r="2.6" fill="#1f4fd1"/></g><text x="460" y="140" fill="#15803d" font-size="11" font-weight="bold">C = 5V</text><g data-sym="nmos"><line x1="340" y1="170" x2="354" y2="170" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="354" y1="158" x2="354" y2="182" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="361" y1="157" x2="361" y2="183" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="361" y1="162" x2="374" y2="162" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="374" y1="162" x2="374" y2="150" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="374" y1="150" x2="396" y2="150" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="361" y1="178" x2="374" y2="178" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="374" y1="178" x2="374" y2="190" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="374" y1="190" x2="396" y2="190" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="361" y1="170" x2="374" y2="170" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polygon points="367,166 367,174 361,170" fill="#1f4fd1" stroke="#1f4fd1" stroke-width="1"/><line x1="374" y1="170" x2="374" y2="178" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="388" y1="190" x2="388" y2="176" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polygon points="382,176 394,176 388,164" fill="none" stroke="#1f4fd1" stroke-width="2"/><line x1="382" y1="164" x2="394" y2="164" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="388" y1="164" x2="388" y2="150" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="340" y="206" fill="#1d2943" font-size="11" text-anchor="end" font-weight="bold">Q28</text><line x1="396" y1="190" x2="396" y2="214" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="ground"><line x1="396" y1="214" x2="396" y2="228" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="384" y1="228" x2="408" y2="228" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="388" y1="233" x2="404" y2="233" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="392" y1="238" x2="400" y2="238" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="10" y="272" fill="#1d2943" font-size="11">Q27 on: B is pulled to GND. ID = 12V / 10k = 1.2mA</text><text x="10" y="292" fill="#64748b" font-size="11">Q28 off: no current in R453, so C sits at 5V. BSS138 VTH = 1.5V typ.</text></svg></div>$vsq$ as box) n
 where question like $q$%BSS138 NMOS 電路分析%$q$;

-- q8：SPI 串聯端接電阻放源端
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="226" viewBox="0 0 520 226" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="226" fill="#0a0a1a"/><text x="260" y="18" fill="#00d4ff" font-size="13" font-weight="bold" text-anchor="middle">SPI series termination: resistor at the source end</text><rect x="30" y="70" width="110" height="100" rx="4" fill="none" stroke="#00ff88" stroke-width="1.6"/><text x="85" y="126" fill="#00ff88" font-size="12" text-anchor="middle" font-weight="bold">Master</text><rect x="350" y="70" width="110" height="100" rx="4" fill="none" stroke="#888" stroke-width="1.6"/><text x="405" y="126" fill="#888" font-size="12" text-anchor="middle" font-weight="bold">Slave</text><line x1="140" y1="88" x2="350" y2="88" stroke="#ffc107" stroke-width="1.8"/><rect x="155" y="80" width="28" height="16" fill="#0a0a1a" stroke="#ffc107" stroke-width="1.4"/><polygon points="196,84 196,92 206,88" fill="#ffc107"/><text x="245" y="84" fill="#ffc107" font-size="11" text-anchor="middle">SCLK</text><line x1="140" y1="112" x2="350" y2="112" stroke="#ffc107" stroke-width="1.8"/><rect x="155" y="104" width="28" height="16" fill="#0a0a1a" stroke="#ffc107" stroke-width="1.4"/><polygon points="196,108 196,116 206,112" fill="#ffc107"/><text x="245" y="108" fill="#ffc107" font-size="11" text-anchor="middle">MOSI</text><line x1="140" y1="136" x2="350" y2="136" stroke="#00d4ff" stroke-width="1.8"/><rect x="307" y="128" width="28" height="16" fill="#0a0a1a" stroke="#00d4ff" stroke-width="1.4"/><polygon points="294,132 294,140 284,136" fill="#00d4ff"/><text x="245" y="132" fill="#00d4ff" font-size="11" text-anchor="middle">MISO</text><line x1="140" y1="160" x2="350" y2="160" stroke="#ffc107" stroke-width="1.8"/><rect x="155" y="152" width="28" height="16" fill="#0a0a1a" stroke="#ffc107" stroke-width="1.4"/><polygon points="196,156 196,164 206,160" fill="#ffc107"/><text x="245" y="156" fill="#ffc107" font-size="11" text-anchor="middle">CS#</text><text x="169" y="60" fill="#ffc107" font-size="11" text-anchor="middle">22-33R here</text><text x="321" y="192" fill="#00d4ff" font-size="11" text-anchor="middle">MISO: source is the Slave</text><text x="10" y="212" fill="#888" font-size="11">R = Z0 - Rout. Series termination damps reflections and slows the edge: less overshoot, less EMI.</text></svg></div>$vsq$ as box) n
 where question like $q$%SPI 線路設計時常會串一個電阻%$q$;

-- q9：同步 vs 非同步 Buck
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="252" viewBox="0 0 520 252" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="252" fill="#0a0a1a"/><text x="260" y="18" fill="#00d4ff" font-size="13" font-weight="bold" text-anchor="middle">Synchronous vs Non-synchronous Buck</text><text x="110" y="34" fill="#00ff88" font-size="12" font-weight="bold" text-anchor="middle">Synchronous  (the answer)</text><text x="370" y="34" fill="#888" font-size="12" font-weight="bold" text-anchor="middle">Non-synchronous</text><text x="12" y="44" fill="#ff6b6b" font-size="11">VIN</text><line x1="42" y1="50" x2="58" y2="50" stroke="#ff6b6b" stroke-width="1.6"/><rect x="58" y="38" width="36" height="24" rx="3" fill="none" stroke="#00ff88" stroke-width="1.6"/><text x="76" y="54" fill="#00ff88" font-size="11" text-anchor="middle">HS</text><line x1="76" y1="62" x2="76" y2="104" stroke="#ffc107" stroke-width="2"/><text x="50" y="88" fill="#ffc107" font-size="11" text-anchor="end">SW</text><line x1="76" y1="92" x2="92" y2="92" stroke="#ffc107" stroke-width="2"/><rect x="92" y="82" width="46" height="20" fill="none" stroke="#00d4ff" stroke-width="1.6"/><text x="115" y="97" fill="#00d4ff" font-size="11" text-anchor="middle">L</text><line x1="138" y1="92" x2="170" y2="92" stroke="#888" stroke-width="1.6"/><circle cx="170" cy="92" r="3" fill="#888"/><line x1="170" y1="92" x2="170" y2="112" stroke="#888" stroke-width="1.6"/><rect x="152" y="112" width="36" height="28" rx="3" fill="none" stroke="#888" stroke-width="1.6"/><text x="170" y="131" fill="#888" font-size="11" text-anchor="middle">Load</text><line x1="170" y1="140" x2="170" y2="158" stroke="#888" stroke-width="1.6"/><line x1="58" y1="158" x2="188" y2="158" stroke="#888" stroke-width="1.6"/><rect x="58" y="104" width="36" height="24" rx="3" fill="none" stroke="#00d4ff" stroke-width="1.6"/><text x="76" y="120" fill="#00d4ff" font-size="11" text-anchor="middle">LS</text><line x1="76" y1="128" x2="76" y2="158" stroke="#888" stroke-width="1.6"/><text x="272" y="44" fill="#ff6b6b" font-size="11">VIN</text><line x1="302" y1="50" x2="318" y2="50" stroke="#ff6b6b" stroke-width="1.6"/><rect x="318" y="38" width="36" height="24" rx="3" fill="none" stroke="#00ff88" stroke-width="1.6"/><text x="336" y="54" fill="#00ff88" font-size="11" text-anchor="middle">HS</text><line x1="336" y1="62" x2="336" y2="104" stroke="#ffc107" stroke-width="2"/><text x="310" y="88" fill="#ffc107" font-size="11" text-anchor="end">SW</text><line x1="336" y1="92" x2="352" y2="92" stroke="#ffc107" stroke-width="2"/><rect x="352" y="82" width="46" height="20" fill="none" stroke="#00d4ff" stroke-width="1.6"/><text x="375" y="97" fill="#00d4ff" font-size="11" text-anchor="middle">L</text><line x1="398" y1="92" x2="430" y2="92" stroke="#888" stroke-width="1.6"/><circle cx="430" cy="92" r="3" fill="#888"/><line x1="430" y1="92" x2="430" y2="112" stroke="#888" stroke-width="1.6"/><rect x="412" y="112" width="36" height="28" rx="3" fill="none" stroke="#888" stroke-width="1.6"/><text x="430" y="131" fill="#888" font-size="11" text-anchor="middle">Load</text><line x1="430" y1="140" x2="430" y2="158" stroke="#888" stroke-width="1.6"/><line x1="318" y1="158" x2="448" y2="158" stroke="#888" stroke-width="1.6"/><line x1="328" y1="112" x2="344" y2="112" stroke="#ffc107" stroke-width="1.8"/><polygon points="328,126 344,126 336,112" fill="none" stroke="#ffc107" stroke-width="1.6"/><line x1="336" y1="104" x2="336" y2="112" stroke="#888" stroke-width="1.6"/><line x1="336" y1="126" x2="336" y2="158" stroke="#888" stroke-width="1.6"/><text x="352" y="122" fill="#ffc107" font-size="11">D</text><line x1="252" y1="30" x2="252" y2="180" stroke="#334155" stroke-width="1"/><text x="10" y="196" fill="#00ff88" font-size="11">low side is a MOSFET</text><text x="10" y="214" fill="#c8d4ee" font-size="11">drop = ID x RDS(on), better efficiency</text><text x="10" y="232" fill="#ff6b6b" font-size="11">needs dead time (no shoot-through)</text><text x="270" y="196" fill="#888" font-size="11">low side is a Schottky diode</text><text x="270" y="214" fill="#c8d4ee" font-size="11">drop = VF 0.3-0.5V, fixed loss</text><text x="270" y="232" fill="#ff6b6b" font-size="11">cheaper, worse at low VOUT</text></svg></div>$vsq$ as box) n
 where question like $q$%若下管為%$q$;

-- q10：上管 OFF 時的續流路徑
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="244" viewBox="0 0 520 244" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="244" fill="#0a0a1a"/><text x="260" y="18" fill="#00d4ff" font-size="13" font-weight="bold" text-anchor="middle">Freewheeling path when HS turns OFF</text><path d="M118,158 V100 H86 V92 H218 V158 H118" fill="none" stroke="#eab308" stroke-width="7" stroke-opacity="0.35" stroke-linecap="round" stroke-linejoin="round"/><text x="22" y="44" fill="#ff6b6b" font-size="11">VIN</text><line x1="52" y1="50" x2="68" y2="50" stroke="#ff6b6b" stroke-width="1.6"/><rect x="68" y="38" width="36" height="24" rx="3" fill="none" stroke="#666" stroke-width="1.6"/><text x="86" y="54" fill="#666" font-size="11" text-anchor="middle">HS</text><text x="110" y="46" fill="#ff6b6b" font-size="11">OFF</text><line x1="86" y1="62" x2="86" y2="104" stroke="#ffc107" stroke-width="2"/><text x="60" y="80" fill="#ffc107" font-size="11" text-anchor="end">SW</text><line x1="86" y1="92" x2="102" y2="92" stroke="#ffc107" stroke-width="2"/><rect x="102" y="82" width="46" height="20" fill="none" stroke="#00d4ff" stroke-width="1.6"/><text x="125" y="97" fill="#00d4ff" font-size="11" text-anchor="middle">L</text><line x1="148" y1="92" x2="218" y2="92" stroke="#888" stroke-width="1.6"/><circle cx="218" cy="92" r="3" fill="#888"/><line x1="218" y1="92" x2="218" y2="112" stroke="#888" stroke-width="1.6"/><rect x="200" y="112" width="36" height="28" rx="3" fill="none" stroke="#888" stroke-width="1.6"/><text x="218" y="131" fill="#888" font-size="11" text-anchor="middle">Load</text><line x1="218" y1="140" x2="218" y2="158" stroke="#888" stroke-width="1.6"/><rect x="68" y="104" width="36" height="24" rx="3" fill="none" stroke="#00d4ff" stroke-width="1.6"/><text x="86" y="120" fill="#00d4ff" font-size="11" text-anchor="middle">LS</text><line x1="86" y1="128" x2="86" y2="158" stroke="#888" stroke-width="1.6"/><line x1="68" y1="158" x2="236" y2="158" stroke="#888" stroke-width="1.6"/><text x="240" y="162" fill="#888" font-size="11">GND</text><circle cx="86" cy="100" r="3" fill="#ffc107"/><line x1="86" y1="100" x2="118" y2="100" stroke="#888" stroke-width="1.4"/><line x1="118" y1="100" x2="118" y2="112" stroke="#888" stroke-width="1.4"/><line x1="110" y1="112" x2="126" y2="112" stroke="#ffc107" stroke-width="1.8"/><polygon points="110,126 126,126 118,112" fill="none" stroke="#ffc107" stroke-width="1.6"/><line x1="118" y1="126" x2="118" y2="158" stroke="#888" stroke-width="1.4"/><text x="132" y="146" fill="#ffc107" font-size="11">body diode</text><text x="270" y="60" fill="#c8d4ee" font-size="11">HS opens, but iL cannot stop:</text><text x="270" y="78" fill="#c8d4ee" font-size="11">V = L x di/dt would spike.</text><text x="270" y="102" fill="#00ff88" font-size="11">The diode hands iL a path</text><text x="270" y="120" fill="#00ff88" font-size="11">(yellow loop, GND -&gt; SW -&gt; L).</text><text x="270" y="144" fill="#ffc107" font-size="11">Sync buck: it is the LS FET</text><text x="270" y="162" fill="#ffc107" font-size="11">body diode, VF ~0.7V, lossy.</text><text x="270" y="186" fill="#888" font-size="11">Non-sync: a real Schottky,</text><text x="270" y="204" fill="#888" font-size="11">VF ~0.3V.</text><text x="10" y="232" fill="#888" font-size="11">Keep dead time short: it is the interval where the lossy diode, not the FET channel, carries iL.</text></svg></div>$vsq$ as box) n
 where question like $q$%Buck 電路中的%$q$;

-- q11：RC Snubber 與振鈴抑制
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="252" viewBox="0 0 520 252" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="252" fill="#0a0a1a"/><text x="260" y="18" fill="#00d4ff" font-size="13" font-weight="bold" text-anchor="middle">RC Snubber across the switch</text><text x="14" y="54" fill="#ff6b6b" font-size="11">VIN</text><line x1="48" y1="50" x2="96" y2="50" stroke="#ff6b6b" stroke-width="1.6"/><rect x="96" y="40" width="42" height="20" fill="none" stroke="#c8d4ee" stroke-width="1.6"/><text x="117" y="54" fill="#c8d4ee" font-size="11" text-anchor="middle">Lstry</text><line x1="138" y1="50" x2="180" y2="50" stroke="#ff6b6b" stroke-width="1.6"/><line x1="180" y1="50" x2="180" y2="80" stroke="#ffc107" stroke-width="2"/><circle cx="180" cy="66" r="3" fill="#ffc107"/><rect x="162" y="80" width="36" height="26" rx="3" fill="none" stroke="#00d4ff" stroke-width="1.6"/><text x="180" y="97" fill="#00d4ff" font-size="11" text-anchor="middle">Q1</text><line x1="180" y1="106" x2="180" y2="140" stroke="#888" stroke-width="1.6"/><line x1="120" y1="140" x2="266" y2="140" stroke="#888" stroke-width="1.6"/><line x1="132" y1="140" x2="168" y2="140" stroke="#888" stroke-width="1.6"/><line x1="138" y1="145" x2="162" y2="145" stroke="#888" stroke-width="1.4"/><line x1="144" y1="150" x2="156" y2="150" stroke="#888" stroke-width="1.2"/><line x1="180" y1="66" x2="212" y2="66" stroke="#00ff88" stroke-width="1.6"/><rect x="212" y="56" width="36" height="20" fill="none" stroke="#00ff88" stroke-width="1.6"/><text x="230" y="70" fill="#00ff88" font-size="11" text-anchor="middle">R</text><line x1="248" y1="66" x2="266" y2="66" stroke="#00ff88" stroke-width="1.6"/><line x1="266" y1="66" x2="266" y2="96" stroke="#00ff88" stroke-width="1.6"/><line x1="254" y1="96" x2="278" y2="96" stroke="#00ff88" stroke-width="2"/><line x1="254" y1="104" x2="278" y2="104" stroke="#00ff88" stroke-width="2"/><text x="284" y="104" fill="#00ff88" font-size="11">C</text><line x1="266" y1="104" x2="266" y2="140" stroke="#00ff88" stroke-width="1.6"/><text x="10" y="166" fill="#00ff88" font-size="11">snubber sits across D-S, as close to Q1 as possible</text><line x1="316" y1="150" x2="316" y2="40" stroke="#888" stroke-width="1.2"/><line x1="316" y1="150" x2="500" y2="150" stroke="#888" stroke-width="1.2"/><polyline points="320,150.0 322,146.4 324,140.4 326,132.3 328,122.7 330,112.2 332,101.3 334,90.7 336,80.8 338,72.0 340,64.7 342,59.2 344,55.5 346,53.8 348,54.0 350,55.9 352,59.3 354,64.0 356,69.6 358,75.8 360,82.3 362,88.7 364,94.7 366,100.1 368,104.6 370,108.1 372,110.4 374,111.6 376,111.6 378,110.6 380,108.7 382,106.0 384,102.7 386,99.0 388,95.1 390,91.3 392,87.6 394,84.4 396,81.6 398,79.4 400,78.0 402,77.1 404,77.0 406,77.5 408,78.6 410,80.2 412,82.1 414,84.3 416,86.6 418,88.9 420,91.1 422,93.1 424,94.8 426,96.2 428,97.1 430,97.6 432,97.8 434,97.5 436,96.9 438,96.0 440,94.9 442,93.6 444,92.2 446,90.8 448,89.5 450,88.3 452,87.3 454,86.4 456,85.8 458,85.5 460,85.3 462,85.5 464,85.8 466,86.3 468,87.0 470,87.7 472,88.6 474,89.4 476,90.2 478,90.9 480,91.6 482,92.1 484,92.5 486,92.7 488,92.8 490,92.7" fill="none" stroke="#ff6b6b" stroke-width="1.8"/><polyline points="320,150.0 322,142.9 324,136.7 326,131.2 328,126.4 330,122.1 332,118.3 334,115.0 336,112.1 338,109.5 340,107.2 342,105.2 344,103.4 346,101.8 348,100.4 350,99.2 352,98.1 354,97.2 356,96.3 358,95.6 360,94.9 362,94.3 364,93.8 366,93.4 368,93.0 370,92.6 372,92.3 374,92.1 376,91.8 378,91.6 380,91.4 382,91.2 384,91.1 386,91.0 388,90.9 390,90.8 392,90.7 394,90.6 396,90.5 398,90.5 400,90.4 402,90.4 404,90.3 406,90.3 408,90.2 410,90.2 412,90.2 414,90.2 416,90.1 418,90.1 420,90.1 422,90.1 424,90.1 426,90.1 428,90.1 430,90.1 432,90.1 434,90.0 436,90.0 438,90.0 440,90.0 442,90.0 444,90.0 446,90.0 448,90.0 450,90.0 452,90.0 454,90.0 456,90.0 458,90.0 460,90.0 462,90.0 464,90.0 466,90.0 468,90.0 470,90.0 472,90.0 474,90.0 476,90.0 478,90.0 480,90.0 482,90.0 484,90.0 486,90.0 488,90.0 490,90.0" fill="none" stroke="#00ff88" stroke-width="1.8"/><text x="312" y="36" fill="#888" font-size="11" text-anchor="end">VDS</text><text x="330" y="34" fill="#ff6b6b" font-size="11">no snubber: ringing + overshoot</text><text x="400" y="140" fill="#00ff88" font-size="11">with snubber: damped</text><text x="10" y="212" fill="#c8d4ee" font-size="11">R = sqrt(Lstry / Coss),  C &gt; 2 x Coss.  Typical R = 1-10 ohm, C = 100pF-1nF.</text><text x="10" y="234" fill="#888" font-size="11">Trades EMI and VDS overshoot against snubber loss: P = C x VDS^2 x fsw.</text></svg></div>$vsq$ as box) n
 where question like $q$%SR2, SC3 組成的電路%$q$;

-- 驗收：七列的 zh / en 都要 t
select left(question, 22) as q,
       answer like '%<svg%' as zh, answer_en like '%<svg%' as en,
       answer_ja like '%<svg%' as ja, answer_ko like '%<svg%' as ko
  from public.interview_questions
 where question like $q$%BSS138 NMOS 電路分析%$q$
    or question like $q$%SPI 線路設計時常會串一個電阻%$q$
    or question like $q$%若下管為%$q$
    or question like $q$%Buck 電路中的%$q$
    or question like $q$%SR2, SC3 組成的電路%$q$;
